# Vietnamese strings the reviewer should look at closely (index -> reason).
FLAGS = {
    8: "Ô ghi chú VN trong mẫu bị dính 2 câu (loại trừ + VAT) - kiểm tra mẫu gốc",
    14: "ENG cũ ghi 'General Manager'; chức danh Tổng giám đốc thường là 'General Director' - xác nhận",
    48: "ENG cũ ghi 'WHO GMP/GLP/GSP' cả cho mỹ phẩm/TPBVSK; bản mới bám câu VN",
    67: "'Tiền đánh giá' = pre-audit; ENG cũ dịch nhầm là self-inspection (tự thanh tra)",
    112: "Câu VN của mẫu GSP ghi 'kiến thức cơ bản về GMP' - có thể là lỗi, nên là GSP",
    144: "Câu có rủi ro pháp lý (chi phí ngoại giao) - bị loại mặc định",
    151: "Câu có rủi ro pháp lý (tiếp đoàn, thúc đẩy hồ sơ) - cần sửa câu VN",
    162: "Câu có rủi ro pháp lý (thúc đẩy hồ sơ, tiếp đoàn) - bị loại mặc định",
    164: "Lệ phí GSP '21 triệu' - cần xác nhận mức phí hiện hành",
    221: "VN ghi 5 năm, ENG cũ ghi 3 years - bản mới bám VN (5 năm), xác nhận",
}


def main():
    vn = list(json.loads((ROOT / "catalog" / "en_goi_y.json").read_text(encoding="utf-8")))
    assert len(vn) == len(EN), (len(vn), len(EN))
    out = {}
    for i, (v, e) in enumerate(zip(vn, EN)):
        out[v] = {"en": e, "trang_thai": "cho_duyet"}
        if i in FLAGS:
            out[v]["ghi_chu"] = FLAGS[i]
    (ROOT / "catalog" / "song_ngu.json").write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{len(out)} entries -> catalog/song_ngu.json")


if __name__ == "__main__":
    main()
